namespace {
int checks=0;
const char* controls[]={"margin-left","margin-top","margin-right","margin-bottom"};
const char* fields[]={"margin.left","margin.top","margin.right","margin.bottom"};
const char* sources[]={"10\n+ 0.5","20\n+ 0.5","30\n+ 0.5","40\n+ 0.5"};
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(15);}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error(("Missing control: "+name).toStdString());}
QString name(int field,const char* suffix){return QString(controls[field])+suffix;}
void reveal(QWidget* c){for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(c->isVisible(),"Exact production control visible");}
std::optional<Expression>& expression(Margin& g,int field){std::optional<Expression>* field_sources[]={&g.left_expression,&g.top_expression,&g.right_expression,&g.bottom_expression};return *field_sources[field];}
std::optional<Ref>& driver(Margin& g,int field){std::optional<Ref>* field_drivers[]={&g.left_driver,&g.top_driver,&g.right_driver,&g.bottom_driver};return *field_drivers[field];}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full Document native-valid BEFORE Window");}
Document fixture(int mode){
 const int field=mode;const bool linked=false;auto d=empty_document("margin-expression-draft-"+std::to_string(mode),"composition","board");auto& comp=d.compositions.front();auto& b=comp.artboards.front();b.width=1200;b.height=900;
 b.layout=ArtboardLayout{Margin{10.123456789012345,20.234567890123456,30.345678901234567,40.456789012345678},Grid{"grid",{15.123456789012345,20.234567890123456,1000.1234567890123,800.23456789012345},3,2,7.345678901234567,8.456789012345678}};
 auto& g=*b.layout->margin;const double literals[]={g.left,g.top,g.right,g.bottom};const int sibling=(field+1)%4;expression(g,sibling)=Expression{QString::number(literals[sibling],'g',17).toStdString(),1};
 const double driven[]={11,21,31,41};if(linked)driver(g,field)=Ref{"driver","","artboard.width"};comp.artboards.push_back({"driver","Driver",1500,0,driven[field],900});
 Object o;o.id="sentinel";o.kind=Kind::path;Contour c;c.id="contour";Point p;p.id="point";p.x.literal=51.25;p.y.literal=-21.75;c.points={p};o.contours={c};d.objects.emplace(o.id,o);comp.roots={o.id};valid(d);return d;
}
Document wanted(const Document& initial,int field){auto d=initial;auto& g=*d.compositions.front().artboards.front().layout->margin;driver(g,field).reset();expression(g,field)=Expression{sources[field],1};valid(d);return d;}
std::vector<Command> command(int field,bool replace,const char* source=nullptr){const Ref ref{"board","",fields[field]};const Expression e{source?source:sources[field],1};switch(field){case 0:return {MarginLeftCommand{SetMarginLeftExpression{ref,e,replace}}};case 1:return {MarginTopCommand{SetMarginTopExpression{ref,e,replace}}};case 2:return {MarginRightCommand{SetMarginRightExpression{ref,e,replace}}};default:return {MarginBottomCommand{SetMarginBottomExpression{ref,e,replace}}};}}
void same(const Session& a,const Session& b){if(!(a.document()==b.document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation()))std::cerr<<"Snapshot doc="<<(a.document()==b.document())<<" history="<<(a.history()==b.history())<<" rev="<<a.revision()<<"/"<<b.revision()<<" active="<<a.gesture_active()<<"/"<<b.gesture_active()<<" gen="<<a.gesture_generation()<<"/"<<b.gesture_generation()<<"\n";check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Full canonical Session equals independent pre-Window expectation");}
void write(const QString& path,const Document& d){QFile f(path);const auto bytes=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(bytes.data(),bytes.size())==static_cast<qint64>(bytes.size()),"Independent native oracle retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
QString prefix(const QString& root,int mode){return root+"/mode-"+QString::number(mode);}
void open(Window& w,const Document& d){w.host.session=Session(d);w.host.edited();w.canvas->set_active_artboard("composition","board",false);w.resize(1400,1000);w.show();w.activateWindow();events();auto* dock=w.findChild<QDockWidget*>("properties");check(dock,"Properties exists");dock->show();dock->raise();events();auto* edit=control<QPushButton>(w,"artboard-edit");reveal(edit);edit->click();events();}
void draft(Window& w,int field,const QString& body=QString{}){
 const auto text=body.isNull()?QString(sources[field]):body;auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_A,Qt::ControlModifier);const auto lines=text.split('\n');for(int i=0;i<lines.size();++i){if(i)QTest::keyClick(editor,Qt::Key_Return);QTest::keyClicks(editor,lines[i]);}events();check(editor->toPlainText()==text,"Exact source draft retained");
}
void apply(Window& w,int field){auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_Return,Qt::ControlModifier);events();}
void reset(Window& w,const Document& d,const QString& key){w.host.session=Session(d);w.host.session_id+=key;w.host.edited();events();}
void cold(const QString& root,int mode){const auto d=wanted(fixture(mode),mode);Session expected(d);const auto path=prefix(root,mode);QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-cold",std::make_unique<FolderLibrary>(settings),&settings);w.host.open(path+"-cold-input.nect");same(w.host.session,expected);w.host.save(path+"-resaved.nect");w.host.flush();same(w.host.session,expected);check(read(path+"-cold-input.nect")==read(path+"-expected.nect")&&read(path+"-resaved.nect")==read(path+"-expected.nect"),"Separate cold exact expression native bytes");QTest::qWait(120);}

void flow(const QString& root,int mode){
 const int field=mode;const auto initial=fixture(mode),intended=wanted(initial,field);Session before(initial),committed(initial);committed.apply(command(field,false),0);check(committed.document()==intended,"Canonical source command matches independent full Document BEFORE Window");
 auto incoming=initial.compositions.front().artboards.front();incoming.name="External revision";Session newer(initial);newer.apply({UpdateArtboard{"composition",incoming}},0);auto newer_intended=intended;newer_intended.compositions.front().artboards.front().name=incoming.name;valid(newer_intended);auto refreshed_commit=newer;refreshed_commit.apply(command(field,false),1);check(refreshed_commit.document()==newer_intended,"Independent fresh-after-cancel source commit BEFORE Window");
 auto replacement=initial;replacement.id+="-replacement";valid(replacement);Session replaced(replacement);auto foreign=before;foreign.begin_gesture(0);foreign.update_gesture({UpdateArtboard{"composition",incoming}});
 Session invalid(initial);QString invalid_error;try{invalid.apply(command(field,false,"1 / 0"),0);}catch(const Error& e){invalid_error=QString::fromStdString(e.code);}check(!invalid_error.isEmpty(),"Independent invalid source refusal BEFORE Window");same(invalid,before);
 const auto flat=QString(sources[field]).replace('\n',' ');auto prefix_intended=initial;expression(*prefix_intended.compositions.front().artboards.front().layout->margin,field)=Expression{flat.toStdString(),1};valid(prefix_intended);Session prefix_commit(initial);prefix_commit.apply(command(field,false,flat.toStdString().c_str()),0);check(prefix_commit.document()==prefix_intended,"Prefix-created source full independent expectation BEFORE Window");
 const auto path=prefix(root,mode);write(path+"-initial.nect",initial);write(path+"-expected.nect",intended);QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-recovery",std::make_unique<FolderLibrary>(settings),&settings);open(w,initial);same(w.host.session,before);draft(w,field);same(w.host.session,before);const int other=(field+2)%4;draft(w,other);same(w.host.session,before);auto* source=control<QPlainTextEdit>(w,name(field,"-expression"));check(source->parentWidget()->grab().save(path+"-draft-before-refresh.png"),"Actual pending source render retained");
 w.host.save(path+"-draft-save.nect");w.host.flush();events();same(w.host.session,before);check(read(path+"-draft-save.nect")==read(path+"-initial.nect"),"Pending source excluded from native save after refresh");
 source=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(source);check(source->parentWidget()->grab().save(path+"-draft-after-refresh.png"),"Actual fresh source control render retained");
 std::cout<<"REFRESH field="<<field<<" source="<<source->toPlainText().toStdString()<<" expected="<<sources[field]<<"\n";
 check(source->toPlainText()==sources[field],"Same Session native Save/Inspector refresh retains exact pending source draft");check(control<QPlainTextEdit>(w,name(other,"-expression"))->toPlainText()==sources[other],"Independent sibling pending source survives same refresh");
 apply(w,field);same(w.host.session,committed);check(control<QPlainTextEdit>(w,name(other,"-expression"))->toPlainText()==sources[other],"Committing one draft retains sibling pending source");apply(w,other);same(w.host.session,committed);check(w.statusBar()->currentMessage().contains("REVISION_CONFLICT"),"Sibling retained draft keeps its original revision after another source commits");source=control<QPlainTextEdit>(w,name(field,"-expression"));check(source->toPlainText()==sources[field],"Existing source command commits retained draft");w.host.save(path+"-saved.nect");w.host.flush();same(w.host.session,committed);check(QFile::copy(path+"-saved.nect",path+"-cold-input.nect"),"Actual saved source bytes retained");QProcess child;child.start(QCoreApplication::applicationFilePath(),{"--cold",root,QString::number(mode)});check(child.waitForStarted(5000),"Owned cold starts");if(!child.waitForFinished(15000)){child.kill();child.waitForFinished();throw std::runtime_error("Owned cold deadline");}std::cout<<child.readAllStandardOutput().toStdString();std::cerr<<child.readAllStandardError().toStdString();check(child.exitStatus()==QProcess::NormalExit&&child.exitCode()==0,"Separate cold acceptance passes");
 w.host.session.undo(w.host.session.revision());committed.undo(committed.revision());w.host.edited();events();same(w.host.session,committed);check(w.host.session.document()==initial,"One Undo restores full authored sources/literals/IDs");check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Successful source commit does not resurrect an unsaved draft after Undo");w.host.session.redo(w.host.session.revision());committed.redo(committed.revision());w.host.edited();events();same(w.host.session,committed);
 reset(w,initial,"-cancel");draft(w,field);w.host.edited();events();source=control<QPlainTextEdit>(w,name(field,"-expression"));check(source->toPlainText()==sources[field],"Unchanged Session edited notification retains source draft");QTest::keyClick(source,Qt::Key_Escape);events();same(w.host.session,before);w.host.edited();events();check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Explicit Cancel clears only view source and stays cleared after refresh");
 reset(w,initial,"-new-revision");draft(w,field);w.host.session.apply({UpdateArtboard{"composition",incoming}},0);w.host.edited();events();same(w.host.session,newer);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==sources[field],"Changed revision retains pending text for inspection");apply(w,field);same(w.host.session,newer);check(w.statusBar()->currentMessage().contains("REVISION_CONFLICT"),"Retained stale draft cannot acquire fresh revision through rebuild");control<QPushButton>(w,name(field,"-apply-expression"))->click();events();same(w.host.session,newer);check(w.statusBar()->currentMessage().contains("REVISION_CONFLICT"),"Existing Apply button has same stale-draft refusal");source=control<QPlainTextEdit>(w,name(field,"-expression"));QTest::keyClick(source,Qt::Key_Escape);events();draft(w,field);apply(w,field);same(w.host.session,refreshed_commit);
 reset(w,initial,"-changed-session");draft(w,field);w.host.session_id+="-new";w.host.edited();events();same(w.host.session,before);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Source draft cannot transfer to replacement Session");
 reset(w,initial,"-changed-document");draft(w,field);w.host.session=Session(replacement);w.host.edited();events();same(w.host.session,replaced);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Same Session/revision source draft cannot transfer to replacement Document");
 reset(w,initial,"-invalid");draft(w,field,"1 / 0");w.host.edited();events();apply(w,field);same(w.host.session,before);check(w.statusBar()->currentMessage().contains(invalid_error),"Invalid retained source refuses canonical command");w.host.edited();events();check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()=="1 / 0","Invalid draft remains editable after refresh");
 reset(w,initial,"-cancel-button");draft(w,field);draft(w,other);w.host.edited();events();control<QPushButton>(w,name(field,"-cancel-expression"))->click();events();same(w.host.session,before);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Existing Cancel expression clears own draft");check(control<QPlainTextEdit>(w,name(other,"-expression"))->toPlainText()==sources[other],"Cancel own source preserves sibling draft");control<QPushButton>(w,name(other,"-cancel"))->click();events();same(w.host.session,before);check(control<QPlainTextEdit>(w,name(other,"-expression"))->toPlainText().isEmpty(),"Existing Cancel draft clears its own source");
 reset(w,initial,"-prefix");auto* n=control<QLineEdit>(w,controls[field]);reveal(n);n->setFocus();QTest::keyClick(n,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(n,"="+flat);QTest::keyClick(n,Qt::Key_Return);events();same(w.host.session,before);w.host.save(path+"-prefix-draft-save.nect");w.host.flush();events();same(w.host.session,before);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==flat,"Numeric prefix-created draft survives same-Session save/refresh");check(read(path+"-prefix-draft-save.nect")==read(path+"-initial.nect"),"Prefix draft remains excluded from native bytes");apply(w,field);same(w.host.session,prefix_commit);
 reset(w,initial,"-foreign");draft(w,field);w.host.session.begin_gesture(0);w.host.session.update_gesture({UpdateArtboard{"composition",incoming}});w.host.edited();events();apply(w,field);same(w.host.session,foreign);source=control<QPlainTextEdit>(w,name(field,"-expression"));QTest::keyClick(source,Qt::Key_Escape);events();same(w.host.session,foreign);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Cancel own source draft preserves foreign gesture and preview");w.host.session.cancel_gesture();
}

}
int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<"\n";if(argc==4&&std::string(argv[1])=="--cold")cold(QString::fromLocal8Bit(argv[2]),std::stoi(argv[3]));else{QTemporaryDir temporary;check(temporary.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_MARGIN_EXPRESSION_DRAFT_ROOT"),root=requested.isEmpty()?temporary.path():requested;int failures=0;for(int mode=0;mode<4;++mode){try{flow(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Independent expression key cases failed: "+std::to_string(failures));}std::cout<<"PASS Margin expression draft refresh "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL Margin expression draft refresh "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
